python3 - <<'EOF'
import re
s=open('app/globals.css').read()
# brand palette tokens
s=s.replace("@theme inline {","""@theme inline {
  --color-brand-red: #A51F18;
  --color-brand-orange: #F15A24;
  --color-brand-gold: #FFC928;
  --color-brand-cream: #FFF8ED;
  --color-brand-brown: #35251E;""",1)
root=s.index(":root {"); end=s.index("}",root)
blk=s[root:end]
blk=re.sub(r"--background:[^;]+;","--background: #FFF8ED;",blk)
blk=re.sub(r"--foreground:[^;]+;","--foreground: #35251E;",blk)
blk=re.sub(r"--primary:[^;]+;","--primary: #A51F18;",blk)
blk=re.sub(r"--primary-foreground:[^;]+;","--primary-foreground: #FFF8ED;",blk)
s=s[:root]+blk+s[end:]
open('app/globals.css','w').write(s)
EOF
